package com.hallisanthe.hallisanthe

import android.os.Bundle
import android.util.Log
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.recyclerview.widget.GridLayoutManager
import com.hallisanthe.hallisanthe.databinding.FragmentCategoriesBinding

class CategoriesFragment : Fragment() {

    private var _binding: FragmentCategoriesBinding? = null
    private val binding get() = _binding!!

    private val categories = listOf(
        Category("", "Pottery"),
        Category("", "Textiles"),
        Category("", "Woodwork"),
        Category("", "Organic"),
        Category("⚒️", "Metalwork"),
        Category("", "Jewelry"),
        Category("", "Paintings"),
        Category("", "Basketry")
    )

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?
    ): View {
        _binding = FragmentCategoriesBinding.inflate(inflater, container, false)

        binding.rvCategories.layoutManager = GridLayoutManager(requireContext(), 2)
        binding.rvCategories.adapter = CategoryAdapter(categories) { selectedCategoryName ->
            navigateToHome(selectedCategoryName)
        }

        return binding.root
    }

    private fun navigateToHome(categoryName: String) {
        try {
            val homeFragment = HomeFragment().apply {
                arguments = Bundle().apply {
                    putString("selected_category", categoryName)
                }
            }
            val activity = requireActivity() as? MainActivity ?: return
            activity.loadFragment(homeFragment)
            activity.setBottomNavSelected(R.id.nav_home)
        } catch (e: Exception) {
            Log.e("CategoriesFragment", "Navigation error: ${e.message}")
        }
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.hallisanthe.hallisanthe

import android.os.Bundle
import android.util.Log
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.Toast
import androidx.fragment.app.Fragment
import androidx.recyclerview.widget.GridLayoutManager
import com.hallisanthe.hallisanthe.databinding.FragmentCategoriesBinding

class CategoriesFragment : Fragment() {

    private var _binding: FragmentCategoriesBinding? = null
    private val binding get() = _binding!!

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?
    ): View {
        _binding = FragmentCategoriesBinding.inflate(inflater, container, false)

        val categories = listOf("Pottery", "Textiles", "Woodwork", "Organic", "Metalwork", "Jewelry", "Paintings", "Basketry")

        val adapter = CategoryAdapter(categories) { selectedCategory ->
            navigateToHomeWithCategory(selectedCategory)
        }

        val recyclerView = _binding!!.rvCategories
        recyclerView.layoutManager = GridLayoutManager(requireContext(), 2)
        recyclerView.adapter = adapter

        return _binding!!.root
    }

    private fun navigateToHomeWithCategory(category: String) {
        try {
            val fragment = HomeFragment()
            val bundle = Bundle()
            bundle.putString("selected_category", category)
            fragment.arguments = bundle

            parentFragmentManager.beginTransaction()
                .replace(R.id.fragment_container, fragment)
                .commit()

            // Update bottom nav selection to Home
            (activity as? MainActivity)?.setBottomNavSelected(R.id.nav_home)
        } catch (e: Exception) {
            Toast.makeText(requireContext(), "Error: ${e.message}", Toast.LENGTH_SHORT).show()
        }
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.hallisanthe.hallisanthe

import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.recyclerview.widget.RecyclerView
import com.hallisanthe.hallisanthe.databinding.ItemCategoryGridBinding

class CategoryAdapter(
    private val categories: List<Category>,
    private val onClick: (String) -> Unit
) : RecyclerView.Adapter<CategoryAdapter.ViewHolder>() {

    class ViewHolder(val binding: ItemCategoryGridBinding) : RecyclerView.ViewHolder(binding.root)

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ViewHolder {
        val binding = ItemCategoryGridBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return ViewHolder(binding)
    }

    override fun onBindViewHolder(holder: ViewHolder, position: Int) {
        val cat = categories[position]
        holder.binding.tvCategoryEmoji.text = cat.emoji
        holder.binding.tvCategoryName.text = cat.name
        holder.binding.root.setOnClickListener { onClick(cat.name) }
    }

    override fun getItemCount() = categories.size
}

package com.hallisanthe.hallisanthe

import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.recyclerview.widget.RecyclerView
import com.hallisanthe.hallisanthe.databinding.ItemCategoryGridBinding

class CategoryAdapter(
    private val categories: List<String>,
    private val onCategoryClick: (String) -> Unit
) : RecyclerView.Adapter<CategoryAdapter.ViewHolder>() {

    private val categoryEmojis = mapOf(
        "Pottery" to "",
        "Textiles" to "",
        "Woodwork" to "",
        "Organic" to "",
        "Metalwork" to "⚒️",
        "Jewelry" to "",
        "Paintings" to "",
        "Basketry" to ""
    )

    class ViewHolder(val binding: ItemCategoryGridBinding) : RecyclerView.ViewHolder(binding.root)

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ViewHolder {
        val binding = ItemCategoryGridBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return ViewHolder(binding)
    }

    override fun onBindViewHolder(holder: ViewHolder, position: Int) {
        val category = categories[position]
        holder.binding.tvCategoryName.text = category
        holder.binding.tvCategoryEmoji.text = categoryEmojis[category] ?: ""
        holder.itemView.setOnClickListener {
            onCategoryClick(category)
        }
    }

    override fun getItemCount() = categories.size
}

package com.hallisanthe.hallisanthe

import android.os.Bundle
import android.util.Log
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.recyclerview.widget.GridLayoutManager
import com.google.android.material.chip.Chip
import com.google.firebase.firestore.FirebaseFirestore
import com.hallisanthe.hallisanthe.databinding.FragmentHomeBinding

class HomeFragment : Fragment() {

    private var _binding: FragmentHomeBinding? = null
    private val binding get() = _binding!!

    private lateinit var adapter: ProductAdapter
    private val allProducts = mutableListOf<Product>()
    private val filteredProducts = mutableListOf<Product>()
    private var selectedCategory = "All"
    private var searchQuery = ""

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        _binding = FragmentHomeBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        binding.recyclerView.layoutManager = GridLayoutManager(requireContext(), 2)
        adapter = ProductAdapter(filteredProducts)
        binding.recyclerView.adapter = adapter

        // Load real products from Firestore
        loadProductsFromFirestore()

        // Handle pre-selected category from CategoriesFragment
        val preselect = arguments?.getString("selected_category")
        if (preselect != null) {
            selectedCategory = preselect
        }

        // Chip click listeners
        binding.chipGroupCategories.setOnCheckedStateChangeListener { group, checkedIds ->
            if (checkedIds.isEmpty()) {
                selectedCategory = "All"
            } else {
                val chip = group.findViewById<Chip>(checkedIds[0])
                val rawText = chip?.text?.toString()?.trim() ?: "All"
                // Extract the English word after the emoji and space: " Trending" -> "Trending"
                selectedCategory = if (rawText.contains(" ")) rawText.substringAfter(" ").trim() else rawText
            }
            applyFilter()
        }

        // Auto-select chip if coming from Categories
        if (preselect != null) {
            for (i in 0 until binding.chipGroupCategories.childCount) {
                val chip = binding.chipGroupCategories.getChildAt(i) as? Chip
                if (chip?.text?.toString()?.contains(preselect, ignoreCase = true) == true) {
                    chip.isChecked = true
                    break
                }
            }
        }

        // Search
        binding.searchView.setOnQueryTextListener(object : androidx.appcompat.widget.SearchView.OnQueryTextListener {
            override fun onQueryTextSubmit(query: String?): Boolean {
                searchQuery = query ?: ""
                applyFilter()
                return true
            }

            override fun onQueryTextChange(newText: String?): Boolean {
                searchQuery = newText ?: ""
                applyFilter()
                return true
            }
        })
    }

    private fun loadProductsFromFirestore() {
        FirebaseFirestore.getInstance()
            .collection("products")
            .addSnapshotListener { snapshot, error ->
                if (!isAdded) return@addSnapshotListener
                if (error != null) {
                    Log.e("HomeFragment", "Firestore error: ${error.message}")
                    return@addSnapshotListener
                }
                allProducts.clear()
                snapshot?.documents?.forEach { doc ->
                    val p = doc.toObject(Product::class.java)
                    if (p != null) allProducts.add(p.copy(id = doc.id))
                }
                applyFilter()
            }
    }

    private fun applyFilter() {
        filteredProducts.clear()

        // "Trending" acts like "All"
        val byCategory = if (selectedCategory == "All" || selectedCategory == "Trending" || selectedCategory.isEmpty()) {
            allProducts.toList()
        } else {
            allProducts.filter { it.category.equals(selectedCategory, ignoreCase = true) }
        }

        val bySearch = if (searchQuery.isEmpty()) {
            byCategory
        } else {
            byCategory.filter {
                it.name.contains(searchQuery, ignoreCase = true) ||
                it.artisanName.contains(searchQuery, ignoreCase = true) ||
                it.villageName.contains(searchQuery, ignoreCase = true)
            }
        }

        // Sort alphabetically within category
        filteredProducts.addAll(bySearch.sortedWith(compareBy({ it.category }, { it.name })))
        adapter.notifyDataSetChanged()
    }

    // ... existing code ...

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}

package com.hallisanthe.hallisanthe

import android.os.Bundle
import android.util.Log
import android.view.LayoutInflater
import android.view.View
